const names={stadium:'INDIGO STADIUM',forest:'VIRIDIAN FOREST',volcano:'CINNABAR CRATER'};
function randomSeed(){return crypto.getRandomValues(new Uint32Array(1))[0]}
function seeded(s){return ()=>{s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296}}
function sprite(id,animated=true){return featured.includes(id)?`assets/${id}.${animated?'gif':'png'}`:`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${animated?'other/showdown/':''}${id}.${animated?'gif':'png'}`}
function setImage(img,id,animated){img.dataset.fallback='0';img.onerror=()=>{if(img.dataset.fallback==='0'){img.dataset.fallback='1';img.src=sprite(id,false)}else{img.onerror=null;img.alt=title(roster.find(p=>p.id===id)?.name||'Pokémon')}};img.src=sprite(id,animated)}
async function data(id){if(cache[id])return cache[id];try{const saved=JSON.parse(localStorage.getItem('bt-pokemon-'+id)||'null');if(saved){cache[id]=saved;return saved}}catch{}const r=await fetch(`https://pokeapi.co/api/v2/pokemon/${id}`,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error('Could not load Pokémon data. Please try again.');const p=await r.json(),d={id:p.id,name:p.name,types:p.types.map(x=>x.type.name),stats:p.stats.map(x=>x.base_stat),moves:p.moves.map(x=>x.move.name)};cache[id]=d;try{localStorage.setItem('bt-pokemon-'+id,JSON.stringify(d))}catch{}return d}
function renderTeams(){teams.forEach((team,t)=>{$('#team-'+(t?'b':'a')).replaceChildren(...team.map((id,s)=>{const b=document.createElement('button');b.className='team-slot';b.disabled=running;b.setAttribute('aria-label',`Replace ${title(cache[id]?.name||'Pokémon')} on Team ${t?'Crimson':'Emerald'}`);const img=document.createElement('img');img.alt='';setImage(img,id,false);const info=document.createElement('span');const strong=document.createElement('strong');strong.textContent=title(cache[id]?.name||roster.find(p=>p.id===id)?.name||'Pokémon');const small=document.createElement('small');small.textContent=cache[id]?.types.join(' / ')||'SELECTED';info.append(strong,small);const edit=document.createElement('span');edit.className='edit';edit.textContent='＋';b.append(img,info,edit);b.onclick=()=>openPicker(t,s);return b}))});}
function saveTeams(){try{localStorage.setItem('bt-teams',JSON.stringify(teams))}catch{}}
function openPicker(t,s){selectSlot=[t,s];filter='featured';limit=60;$('#search').value='';$('#picker-context').textContent=`${t?'CRIMSON':'EMERALD'} / SLOT ${s+1}`;$$('.picker-filters button').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter));renderPicker();$('#picker').showModal();$('#search').focus()}
function renderPicker(){const q=$('#search').value.trim().toLowerCase().replaceAll(' ','-').replace('#','');const found=roster.filter(p=>(q||filter==='all'||featured.includes(p.id))&&(!q||p.name.includes(q)||String(p.id)===q));$('#result-count').textContent=`${found.length} Pokémon · ${Math.min(limit,found.length)} shown`;$('#more').hidden=found.length<=limit;$('#pokemon-grid').replaceChildren(...found.slice(0,limit).map(p=>{const b=document.createElement('button');b.className='pokemon-card';b.disabled=pickerBusy;const img=document.createElement('img');img.alt='';img.loading='lazy';setImage(img,p.id,false);const n=document.createElement('strong');n.textContent=title(p.name);const no=document.createElement('small');no.textContent='#'+String(p.id).padStart(4,'0');b.append(img,n,no);b.onclick=async()=>{if(pickerBusy)return;const [t,s]=selectSlot;if(teams[t].includes(p.id)&&teams[t][s]!==p.id){$('#picker-context').textContent='Already on this team';return}pickerBusy=true;b.textContent='Loading…';try{await data(p.id);teams[t][s]=p.id;saveTeams();$('#picker').close();renderTeams();resetPreview()}catch(e){$('#picker-context').textContent='Load failed — check connection';}finally{pickerBusy=false;renderPicker()}};return b}));if(!found.length){const p=document.createElement('p');p.className='picker-error';p.textContent='No Pokémon found. Try another name or number.';$('#pokemon-grid').append(p)}}
function position(p){return {x:p.team===0?[275,220,335][p.slot]:[925,980,865][p.slot],y:[340,510,620][p.slot]}}
function renderFighters(){const container=$('#fighters');container.replaceChildren(...fighters.map(p=>{const div=document.createElement('div'),pos=position(p);div.className='fighter team-'+(p.team?'b':'a');div.id=p.uid;div.style.left=pos.x/12+'%';div.style.top=(pos.y-60)/7.6+'%';div.style.zIndex=String(2+p.slot);const shadow=document.createElement('span');shadow.className='shadow';const img=document.createElement('img');img.className='sprite';img.alt=title(p.name);setImage(img,p.id,true);const hp=document.createElement('div');hp.className='hp-box';hp.innerHTML='<div class="hp-title"><strong></strong><span></span></div><div class="hp-track"><div class="hp-fill"></div></div>';hp.querySelector('strong').textContent=title(p.name);hp.querySelector('.hp-title span').textContent=p.max+'/'+p.max;div.append(shadow,img,hp);return div}));}
function updateHP(p){const div=document.getElementById(p.uid);div.querySelector('.hp-fill').style.width=Math.max(0,p.hp/p.max*100)+'%';div.querySelector('.hp-title span').textContent=p.hp+'/'+p.max;div.setAttribute('aria-label',`${title(p.name)}, ${p.hp} of ${p.max} HP`);if(p.hp<=0)div.classList.add('fainted')}
function resetPreview(){if(running)return;done=false;$('#result').classList.add('hidden');$('#intro-overlay').classList.remove('hidden');$('#battle-status').textContent='AWAITING CHALLENGERS';$('#playback-label').textContent='Ready when you are';$('#turn').textContent='EXHIBITION / 3 VS 3';$('#replay').disabled=true;fighters=teams.flatMap((team,t)=>team.map((id,s)=>createFighter(cache[id],t,s)));renderFighters()}
function log(text,kind=''){const box=$('#log');box.querySelector('.empty-log')?.remove();const entry=document.createElement('div');entry.className='log-entry '+kind;const time=document.createElement('time');time.textContent=String(round).padStart(2,'0');const content=document.createElement('span');content.textContent=text;entry.append(time,content);box.append(entry);box.scrollTop=box.scrollHeight;$('#log-count').textContent=`${box.children.length} EVENTS`}
function tone(type='charge',pitch=1){if(!sound||!audio)return;const osc=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime;osc.type=type==='hit'?'sawtooth':'sine';osc.frequency.setValueAtTime((type==='charge'?150:type==='win'?520:80)*pitch,t);osc.frequency.exponentialRampToValueAtTime(type==='charge'?600*pitch:40*pitch,t+.24);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.035,t+.025);g.gain.exponentialRampToValueAtTime(.0001,t+.35);osc.connect(g).connect(audio.destination);osc.start(t);osc.stop(t+.4)}
function wait(ms,token){return new Promise(resolve=>{let left=ms,last=performance.now();function tick(now){if(token!==runId){resolve(false);return}if(!paused)left-=(now-last)*speed;last=now;if(left<=0)resolve(true);else requestAnimationFrame(tick)}requestAnimationFrame(tick)})}
function lockUI(){renderTeams();$('#shuffle').disabled=running;$$('.arena-option').forEach(b=>b.disabled=running);$('#start').disabled=running;$('#start').firstChild.textContent=running?'BATTLE IN PROGRESS ':'LET THEM BATTLE ';$('#pause').disabled=!running;$('#replay').disabled=running||!done}
async function start(replay=false){if(running||!fighters.length)return;runId++;const token=runId;running=true;paused=false;done=false;round=0;elapsed=0;particles=[];rings=[];beam=null;startSeed=replay?startSeed:randomSeed();seed=startSeed;rng=seeded(seed);fighters=teams.flatMap((team,t)=>team.map((id,s)=>createFighter(cache[id],t,s)));renderFighters();$('#stage').classList.remove('paused');$('#pause').innerHTML='Ⅱ <span>Pause</span>';$('#intro-overlay').classList.add('hidden');$('#result').classList.add('hidden');$('#log').replaceChildren();$('#battle-status').textContent='BATTLE LIVE';$('#playback-label').textContent='The showdown is live';lockUI();log('The challengers enter the arena. Let the battle begin!');tone('charge');await wait(1100,token);
while(token===runId&&fighters.some(p=>p.team===0&&p.hp>0)&&fighters.some(p=>p.team===1&&p.hp>0)&&round<180){round++;$('#turn').textContent=`TURN ${String(round).padStart(2,'0')} / ${fighters.filter(p=>p.hp>0).length} STILL STANDING`;const attack=chooseAttack(fighters,rng);if(!attack)break;await animateAttack(attack,token);if(!await wait(480,token))return}
if(token!==runId)return;running=false;done=true;const a=fighters.filter(p=>p.team===0&&p.hp>0),b=fighters.filter(p=>p.team===1&&p.hp>0);const winner=!a.length?'Crimson':!b.length?'Emerald':null;$('#result h2').textContent=winner?`TEAM ${winner.toUpperCase()} WINS!`:'A LEGENDARY STALEMATE';$('#result p').textContent=winner?`${(winner==='Emerald'?a:b).map(p=>title(p.name)).join(', ')} ${(winner==='Emerald'?a:b).length===1?'stands':'stand'} victorious after ${round} turns.`:'Neither team fell after 180 turns. Try a new matchup.';$('#result').classList.remove('hidden');$('#battle-status').textContent='BATTLE COMPLETE';$('#playback-label').textContent=winner?`Team ${winner} takes the arena`:'An evenly matched showdown';log(winner?`Team ${winner} wins the battle!`:'The battle ends in a draw.','ko');tone('win');lockUI();}
async function animateAttack(a,token){const {actor,target,move,damage,mult,crit,dodge}=a,c=colors[move.type],source=position(actor),dest=position(target),att=document.getElementById(actor.uid),def=document.getElementById(target.uid);att.style.setProperty('--attack-color',c);att.classList.add('charging');tone('charge',1+actor.slot*.15);log(`${title(actor.name)} uses ${title(move.name)} on ${title(target.name)}!`);const call=$('#move-callout');if(cinematic){call.querySelector('small').textContent=`${title(move.type).toUpperCase()} / ${crit?'CRITICAL MOMENT':'ATTACK INCOMING'}`;call.querySelector('strong').textContent=title(move.name);call.querySelector('span').textContent=title(actor.name)+' → '+title(target.name);call.style.borderColor=c+'88';call.classList.add('visible')}
ring(source.x,source.y-40,c,110);await wait(cinematic?780:320,token);call.classList.remove('visible');att.classList.remove('charging');if(token!==runId)return;
if(move.fx==='melee'||move.fx==='slash'){att.style.transition='left .3s, top .3s';att.style.left=(dest.x+(actor.team?80:-80))/12+'%';att.style.top=(dest.y-60)/7.6+'%';await wait(330,token);burst(dest.x,dest.y-40,c,35);if(move.fx==='slash'){for(let i=0;i<3;i++)rings.push({x:dest.x,y:dest.y-60+i*20,r:20,life:.4,max:.4,c,slash:true})}}
else if(move.fx==='ground'){for(let i=0;i<10;i++)particles.push({x:dest.x+(Math.random()-.5)*160,y:dest.y+30,vx:(Math.random()-.5)*70,vy:-250-Math.random()*250,life:.9,max:.9,size:14+Math.random()*15,c,rock:true});await wait(500,token)}
else if(move.fx==='meteor'){for(let i=0;i<12;i++)particles.push({x:dest.x-160+Math.random()*200,y:dest.y-500-Math.random()*200,vx:180,vy:500,life:1.2,max:1.2,size:9+Math.random()*12,c,trail:true});await wait(700,token)}
else{beam={from:source,to:dest,c,kind:move.fx,life:.7,max:.7};await wait(580,token)}
if(token!==runId)return;if(dodge){def.classList.add('dodging');floatText(target,'DODGED',false);log(`${title(target.name)} dodges the attack!`)}else if(mult===0){floatText(target,'IMMUNE',false);log(`It has no effect on ${title(target.name)}.`)}else{burst(dest.x,dest.y-45,c,cinematic?55:20);ring(dest.x,dest.y-45,c,crit?160:100);def.classList.add('hit');tone('hit',crit?1.8:1);if(cinematic){$('#stage').classList.remove('shake');void $('#stage').offsetWidth;$('#stage').classList.add('shake');$('#flash').style.opacity=crit?'.5':'.2';$('#flash').style.background=c;setTimeout(()=>{$('#flash').style.transition='opacity .3s';$('#flash').style.opacity='0'},70)}target.hp=Math.max(0,target.hp-damage);updateHP(target);floatText(target,`${crit?'CRITICAL! ':''}−${damage}`,crit);log(`${damage} damage.${crit?' A critical hit!':''}${mult>1?' It’s super effective!':mult<1?' Not very effective.':''}`);}
await wait(400,token);att.style.left=source.x/12+'%';att.style.top=(source.y-60)/7.6+'%';def.classList.remove('hit','dodging');if(target.hp<=0){log(`${title(target.name)} fainted!`,'ko');await wait(600,token)}}
function floatText(p,text,critical){const pos=position(p),el=document.createElement('span');el.className='damage-number'+(critical?' critical':'');el.textContent=text;el.style.left=(pos.x-50)/12+'%';el.style.top=(pos.y-150)/7.6+'%';$('#stage').append(el);setTimeout(()=>el.remove(),1300)}
function burst(x,y,c,count){for(let i=0;i<count;i++){const angle=Math.random()*Math.PI*2,v=60+Math.random()*260;particles.push({x,y,vx:Math.cos(angle)*v,vy:Math.sin(angle)*v,life:.4+Math.random()*.5,max:1,size:2+Math.random()*6,c})}}
function ring(x,y,c,r){rings.push({x,y,c,r:10,end:r,life:.6,max:.6})}
function paintEffects(dt){fx.clearRect(0,0,1200,760);fx.save();fx.globalCompositeOperation='lighter';for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.rock)p.vy+=450*dt;fx.globalAlpha=Math.max(0,p.life/p.max);fx.fillStyle=p.c;fx.shadowColor=p.c;fx.shadowBlur=cinematic?15:0;if(p.trail){fx.strokeStyle=p.c;fx.lineWidth=p.size/2;fx.beginPath();fx.moveTo(p.x,p.y);fx.lineTo(p.x-p.vx*.1,p.y-p.vy*.1);fx.stroke()}fx.fillRect(p.x,p.y,p.size,p.size)}particles=particles.filter(p=>p.life>0);for(const r of rings){r.life-=dt;const progress=1-r.life/r.max;fx.globalAlpha=Math.max(0,r.life/r.max);fx.strokeStyle=r.c;fx.lineWidth=r.slash?7:3;fx.shadowColor=r.c;fx.shadowBlur=cinematic?18:0;fx.beginPath();if(r.slash){fx.moveTo(r.x-60,r.y+40);fx.lineTo(r.x+60,r.y-40)}else fx.ellipse(r.x,r.y,r.r+progress*(r.end||100),r.r*.5+progress*(r.end||100)*.6,0,0,Math.PI*2);fx.stroke()}rings=rings.filter(p=>p.life>0);if(beam){beam.life-=dt;const {from,to,c,kind}=beam,t=Math.min(1,(1-beam.life/beam.max)*2),x=from.x+(to.x-from.x)*t,y=from.y-55+(to.y-from.y)*t;fx.globalAlpha=Math.min(1,Math.max(0,beam.life/beam.max*2));fx.shadowColor=c;fx.shadowBlur=cinematic?25:0;fx.strokeStyle=c;fx.fillStyle=c;if(kind==='beam'||kind==='bolt'){fx.lineWidth=kind==='bolt'?5:17;fx.beginPath();fx.moveTo(from.x,from.y-55);for(let i=1;i<=12;i++){const q=i/12;fx.lineTo(from.x+(x-from.x)*q,from.y-55+(y-(from.y-55))*q+(kind==='bolt'?(Math.random()-.5)*50:Math.sin(q*12)*6))}fx.stroke();fx.strokeStyle='#fff';fx.lineWidth=4;fx.stroke()}else if(kind==='wave'){for(let i=0;i<3;i++){fx.lineWidth=5;fx.beginPath();fx.ellipse(x-i*20,y,30+i*12,70+i*12,0,-Math.PI/2,Math.PI/2);fx.stroke()}}else{fx.beginPath();fx.arc(x,y,22,0,Math.PI*2);fx.fill();fx.fillStyle='#fff';fx.beginPath();fx.arc(x-4,y-4,10,0,Math.PI*2);fx.fill()}if(beam.life<=0)beam=null}fx.restore()}
// Original procedural pixel environments: stadium terraces, forest canopies and a lava crater.
function drawArena(){const c=scene,R=seeded(42);c.clearRect(0,0,1200,760);c.imageSmoothingEnabled=false;const grad=c.createLinearGradient(0,0,0,760);grad.addColorStop(0,arena==='volcano'?'#b17b6d':arena==='forest'?'#789b7e':'#b4c5ac');grad.addColorStop(.45,arena==='volcano'?'#564342':arena==='forest'?'#365640':'#6f8c6b');grad.addColorStop(1,'#233d31');c.fillStyle=grad;c.fillRect(0,0,1200,760);
if(arena==='stadium'){for(let row=0;row<13;row++){const y=40+row*16;c.fillStyle=row%2?'#647b6c':'#53695c';c.fillRect(0,y,1200,16);for(let x=0;x<1200;x+=13){c.fillStyle=['#aec29b','#dbc59c','#769d88','#7f909e','#cf9b82'][Math.floor(R()*5)];c.globalAlpha=.4+R()*.4;c.fillRect(x+3,y+3,5,6)}c.globalAlpha=1}c.fillStyle='#324e41';c.fillRect(0,240,1200,35);c.fillStyle='#b6c5a3';c.fillRect(0,238,1200,4);for(const x of [50,1120]){c.fillStyle='#6e7d77';c.fillRect(x,15,13,224);c.fillStyle='#e9e9c8';c.fillRect(x-28,8,70,13);c.fillStyle='#fbf7cc44';c.beginPath();c.moveTo(x-25,20);c.lineTo(x-100,400);c.lineTo(x+190,400);c.lineTo(x+40,20);c.fill()}c.fillStyle='#1c332e';c.fillRect(480,130,240,100);c.strokeStyle='#b2d198';c.lineWidth=3;c.strokeRect(485,135,230,90);c.font='bold 27px monospace';c.fillStyle='#c8dfad';c.textAlign='center';c.fillText('INDIGO LEAGUE',600,172);c.font='13px monospace';c.fillText('CHAMPIONSHIP SERIES',600,200);}
if(arena==='forest'){for(let layer=0;layer<3;layer++){for(let i=0;i<22;i++){const x=R()*1300-50,y=R()*220+layer*35;c.fillStyle=['#627b57','#3c6244','#254c37'][layer];c.fillRect(x,y,18,310-y);for(let j=0;j<5;j++){c.beginPath();c.ellipse(x+(R()-.5)*90,y+j*16,60+R()*35,45,0,0,Math.PI*2);c.fill()}}}}
if(arena==='volcano'){for(let i=0;i<9;i++){const x=i*170-80;c.fillStyle=i%2?'#5f5354':'#6c5b59';c.beginPath();c.moveTo(x-130,320);c.lineTo(x+40,60+R()*170);c.lineTo(x+230,320);c.fill()}c.fillStyle='#ffc47b';c.beginPath();c.moveTo(565,155);c.lineTo(600,100);c.lineTo(635,155);c.closePath();c.fill();}
c.fillStyle=arena==='volcano'?'#574d46':arena==='forest'?'#52724b':'#638351';c.beginPath();c.ellipse(600,520,700,280,0,0,Math.PI*2);c.fill();for(let i=0;i<2800;i++){const x=R()*1200,y=280+R()*480;c.fillStyle=arena==='volcano'?(i%2?'#453d3a':'#73614d'):(i%2?'#a4b77b':'#2e593a');c.globalAlpha=.16+R()*.2;c.fillRect(x,y,2+R()*5,2)}c.globalAlpha=1;
if(arena!=='volcano'){c.strokeStyle='#e5e9bb80';c.lineWidth=3;c.beginPath();c.ellipse(600,515,470,190,0,0,Math.PI*2);c.stroke();c.beginPath();c.moveTo(600,330);c.lineTo(600,705);c.stroke();c.beginPath();c.ellipse(600,515,95,48,0,0,Math.PI*2);c.stroke();c.beginPath();c.ellipse(600,515,24,13,0,0,Math.PI*2);c.fillStyle=arena==='forest'?'#52724b':'#638351';c.fill();c.stroke();}
else{c.lineWidth=5;c.strokeStyle='#ea8d47';c.shadowColor='#ff7d37';c.shadowBlur=15;for(let i=0;i<7;i++){c.beginPath();c.moveTo(i*210,760);let x=i*210;for(let y=760;y>340;y-=45){x+=(R()-.5)*100;c.lineTo(x,y)}c.stroke()}c.shadowBlur=0}
if(arena==='forest'){for(const side of [0,1])for(let i=0;i<15;i++){c.fillStyle=i%2?'#284d35':'#365d3e';const x=side?1160+R()*90:R()*70-30,y=260+R()*500;c.beginPath();c.ellipse(x,y,35+R()*50,30,0,0,7);c.fill()}}
const shade=c.createRadialGradient(600,440,150,600,440,700);shade.addColorStop(0,'#07181000');shade.addColorStop(1,'#08181399');c.fillStyle=shade;c.fillRect(0,0,1200,760)}
function frame(now){const dt=Math.min((now-lastTime)/1000,.05);lastTime=now;if(!paused){ambienceTime+=dt;if(running)elapsed+=dt;paintEffects(dt*speed);if(cinematic&&Math.random()<dt*7){particles.push({x:Math.random()*1200,y:arena==='volcano'?760:Math.random()*760,vx:arena==='forest'?20:0,vy:arena==='volcano'?-35:-8,life:3,max:3,size:2,c:arena==='volcano'?'#ffb67c':'#e4efbb'})}}requestAnimationFrame(frame)}
$('#start').onclick=()=>start();$('#stage-start').onclick=()=>start();$('#rematch').onclick=()=>start();$('#replay').onclick=()=>start(true);$('#pause').onclick=()=>{if(!running)return;paused=!paused;$('#stage').classList.toggle('paused',paused);$('#pause').innerHTML=paused?'▶ <span>Resume</span>':'Ⅱ <span>Pause</span>';$('#playback-label').textContent=paused?'The battle is paused':'The showdown is live'};
$('#sound').onclick=async()=>{sound=!sound;if(sound){audio??=new AudioContext();await audio.resume();tone('win')}$('#sound span').textContent=sound?'ON':'OFF';$('#sound').setAttribute('aria-label',sound?'Mute battle sound':'Enable battle sound')};
$('#cinematic').checked=cinematic;$('#cinematic').onchange=e=>cinematic=e.target.checked;
$$('#speeds button').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);$$('#speeds button').forEach(x=>x.classList.toggle('selected',x===b))});
$$('.arena-option').forEach(b=>b.onclick=()=>{if(running)return;arena=b.dataset.arena;$$('.arena-option').forEach(x=>x.classList.toggle('selected',x===b));$('#arena-name').textContent=names[arena];$('#weather').textContent=arena==='volcano'?'✦ FALLING EMBERS':arena==='forest'?'✦ DAPPLED SUNLIGHT':'✦ CLEAR SKIES';drawArena()});
$('#shuffle').onclick=()=>{if(running)return;const ids=[...featured].sort(()=>Math.random()-.5);teams=[ids.slice(0,3),ids.slice(3,6)];renderTeams();saveTeams();resetPreview()};
$('#close-picker').onclick=()=>$('#picker').close();$('#search').oninput=()=>{limit=60;renderPicker()};$$('.picker-filters button').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;limit=60;$$('.picker-filters button').forEach(x=>x.classList.toggle('selected',x===b));renderPicker()});$('#more').onclick=()=>{limit+=60;renderPicker()};
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.theater').requestFullscreen()}catch{$('#playback-label').textContent='Fullscreen is unavailable in this browser'}};
$('#credits').onclick=()=>$('#credits-dialog').showModal();$('.dialog-close').onclick=()=>$('#credits-dialog').close();
async function init(){try{[cache,roster]=await Promise.all([fetch('pokemon.json').then(r=>r.json()),fetch('roster.json').then(r=>r.json())]);try{const saved=JSON.parse(localStorage.getItem('bt-teams'));if(saved?.length===2&&saved.every(t=>t.length===3&&t.every(id=>Number.isInteger(id)&&id>=1&&id<=1025))){await Promise.all(saved.flat().map(data));teams=saved}}catch{}renderTeams();resetPreview();drawArena();requestAnimationFrame(frame)}catch(e){$('#playback-label').textContent='Could not load battle data. Refresh to retry.';$('#start').disabled=true;$('#stage-start').disabled=true;console.error(e)}}
init();
